SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "贺德伦请晋王入魏州并上印节，李存勖兼领天雄军。", "citation": "卷269·贞明元年（915）·zztj-v269-y0915-p012·原文件第41行", "note": "原文：六月，庚寅朔，贺德伦帅将吏请晋王入府城慰劳。既入，德伦上印节，请王兼领天雄军，王固辞，曰：“比闻汴寇侵逼贵道，故亲董师徒，远来相救。又闻城中新罹涂炭，故暂入存抚。明公不垂鉴信，乃以印节见推，诚非素怀。”德伦再拜曰：“今寇敌密迩，军城新有大变，人心未安。德伦腹心纪纲为张彦所杀殆尽，形孤势弱，安能统众！一旦生事，恐负大恩。”王乃受之。；核对说明：晋王起初推辞，后文“王乃受之”才确认接领；不把初辞当作最终拒绝。", "status": "draft", "id": "1f4ecb17-9d0a-5350-a650-bb400f3ec427", "subject_id": "4b228379-955b-59ae-bd61-120ed17f6031", "source_id": "ac6d777f-7291-5ac1-ad56-ca7318bbfaa6"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "915年六月庚寅朔", "citation": "卷269·贞明元年（915）·zztj-v269-y0915-p012·原文件第41行", "note": "原文：六月，庚寅朔，贺德伦帅将吏请晋王入府城慰劳。既入，德伦上印节，请王兼领天雄军，王固辞，曰：“比闻汴寇侵逼贵道，故亲董师徒，远来相救。又闻城中新罹涂炭，故暂入存抚。明公不垂鉴信，乃以印节见推，诚非素怀。”德伦再拜曰：“今寇敌密迩，军城新有大变，人心未安。德伦腹心纪纲为张彦所杀殆尽，形孤势弱，安能统众！一旦生事，恐负大恩。”王乃受之。；核对说明：按主书段落次序；未把干支换算成公历日。", "status": "draft", "id": "d3b60563-1eee-550c-b380-296c6cb143df", "subject_id": "4b228379-955b-59ae-bd61-120ed17f6031", "source_id": "ac6d777f-7291-5ac1-ad56-ca7318bbfaa6"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记贺德伦：率将吏请晋王入城并上印节的前天雄节度使。", "citation": "卷269·贞明元年（915）·zztj-v269-y0915-p012·原文件第41行", "note": "原文：六月，庚寅朔，贺德伦帅将吏请晋王入府城慰劳。既入，德伦上印节，请王兼领天雄军，王固辞，曰：“比闻汴寇侵逼贵道，故亲董师徒，远来相救。又闻城中新罹涂炭，故暂入存抚。明公不垂鉴信，乃以印节见推，诚非素怀。”德伦再拜曰：“今寇敌密迩，军城新有大变，人心未安。德伦腹心纪纲为张彦所杀殆尽，形孤势弱，安能统众！一旦生事，恐负大恩。”王乃受之。；核对说明：姓名按既有主体规范；原文和摘录保留底本字形。", "status": "draft", "id": "651f886b-34ea-5daa-9ee5-75f112f9678d", "subject_id": "18281df5-a215-5501-b35d-effaa3bb9fd5", "source_id": "ac6d777f-7291-5ac1-ad56-ca7318bbfaa6"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "贺德伦：率将吏请晋王入城并上印节的前天雄节度使。", "citation": "卷269·贞明元年（915）·zztj-v269-y0915-p012·原文件第41行", "note": "原文：六月，庚寅朔，贺德伦帅将吏请晋王入府城慰劳。既入，德伦上印节，请王兼领天雄军，王固辞，曰：“比闻汴寇侵逼贵道，故亲董师徒，远来相